ALTER TABLE "portal"."demo_state_event" DROP CONSTRAINT "demo_state_event_transition_allowed";--> statement-breakpoint
ALTER TABLE "portal"."demo_state_event" ADD CONSTRAINT "demo_state_event_transition_allowed" CHECK (("portal"."demo_state_event"."from_state" IS NULL AND "portal"."demo_state_event"."sequence" = 1 AND "portal"."demo_state_event"."to_state" = 'VERIFIED') OR ("portal"."demo_state_event"."from_state" IS NOT NULL AND ((from_state = 'VERIFIED' AND to_state IN ('CLAIMED', 'WAITING')) OR (from_state = 'WAITING' AND to_state IN ('CLAIMED')) OR (from_state = 'CLAIMED' AND to_state IN ('PROVISIONING', 'WAITING', 'KILLED', 'FROZEN')) OR (from_state = 'PROVISIONING' AND to_state IN ('LIVE', 'FAILED', 'KILLED', 'FROZEN')) OR (from_state = 'LIVE' AND to_state IN ('EXPIRING', 'EXTENDED', 'PROMOTING', 'REBUILDING', 'KILLED', 'FROZEN')) OR (from_state = 'EXTENDED' AND to_state IN ('EXPIRING', 'PROMOTING', 'REBUILDING', 'KILLED', 'FROZEN')) OR (from_state = 'EXPIRING' AND to_state IN ('PURGED', 'EXTENDED', 'PROMOTING', 'KILLED', 'FROZEN')) OR (from_state = 'REBUILDING' AND to_state IN ('LIVE', 'EXTENDED', 'FAILED', 'KILLED', 'FROZEN')) OR (from_state = 'PROMOTING' AND to_state IN ('PROMOTED', 'LIVE', 'EXTENDED', 'EXPIRING', 'KILLED', 'FROZEN')))));
